from math import isqrt

def continued_fraction(a, b):
    """Yield partial quotients of a/b."""
    while b:
        yield a // b
        a, b = b, a % b

def convergents(cf):
    """Generate convergents (num, den) from continued-fraction coefficients."""
    p0, q0 = 0, 1
    p1, q1 = 1, 0
    for a in cf:
        p = a * p1 + p0
        q = a * q1 + q0
        yield p, q
        p0, q0 = p1, q1
        p1, q1 = p, q

def is_perfect_square(x):
    if x < 0:
        return False
    r = isqrt(x)
    return r * r == x

def wiener_attack(e, n):
    """
    Recover a small private exponent d (or None if the key is not vulnerable).
    """
    # Continued-fraction expansion of e/n
    cf = continued_fraction(e, n)

    for k, d in convergents(cf):
        if k == 0:
            continue
        # ed ≡ 1 (mod k)  ⇒  φ = (ed - 1)//k
        if (e * d - 1) % k != 0:
            continue
        phi = (e * d - 1) // k

        # Solve x² - (n-φ+1)x + n = 0 for the primes
        s = n - phi + 1
        disc = s * s - 4 * n
        if not is_perfect_square(disc):
            continue
        t = isqrt(disc)
        if (s + t) % 2 != 0:
            continue
        p = (s + t) // 2
        q = (s - t) // 2
        if p * q == n and p > 1 and q > 1:
            # Optional sanity check
            if pow(pow(2, e, n), d, n) == 2:
                return d
    return None

